INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('6dd9fe27-5250-4b9e-89ad-2742e213ef48', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which IS-IS level supports intra-area routing in Junos OS?', '[{"id": "A", "text": "Level 1", "is_correct": true}, {"id": "B", "text": "Level 2", "is_correct": false}, {"id": "C", "text": "Level 1 and Level 2", "is_correct": false}, {"id": "D", "text": "Level 0", "is_correct": false}]', 'IS-IS Level 1 handles intra-area (within area) routing. Level 2 handles inter-area routing between different areas.', '{"https://www.juniper.net/documentation/us/en/software/junos/is-is/"}', 'IS-IS', 12.0, '{"ru": "Какой уровень IS-IS поддерживает маршрутизацию внутри зоны в Junos OS?"}', '{"ru": [{"id": "A", "text": "Level 1"}, {"id": "B", "text": "Level 2"}, {"id": "C", "text": "Level 1 and Level 2"}, {"id": "D", "text": "Level 0"}]}', '2ac2003d410beb84_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('be02741e-549a-4a9a-823f-e63cec649d3b', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is the default OSPF hello interval on a broadcast network in Junos OS?', '[{"id": "A", "text": "10 seconds", "is_correct": true}, {"id": "B", "text": "30 seconds", "is_correct": false}, {"id": "C", "text": "40 seconds", "is_correct": false}, {"id": "D", "text": "5 seconds", "is_correct": false}]', 'OSPF hello interval defaults to 10 seconds on broadcast and point-to-point networks, and 30 seconds on NBMA networks.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF', 12.0, '{"ru": "Каков интервал Hello по умолчанию для OSPF на широковещательной сети в Junos OS?"}', '{"ru": [{"id": "A", "text": "10 seconds"}, {"id": "B", "text": "30 seconds"}, {"id": "C", "text": "40 seconds"}, {"id": "D", "text": "5 seconds"}]}', 'c2ffaa9499be5749_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('4a66ed0c-57f5-4e49-8345-2ca1fa168504', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'understand', 'Which BGP attribute is used for loop prevention within an AS?', '[{"id": "A", "text": "AS_PATH", "is_correct": true}, {"id": "B", "text": "NEXT_HOP", "is_correct": false}, {"id": "C", "text": "LOCAL_PREF", "is_correct": false}, {"id": "D", "text": "MED", "is_correct": false}]', 'AS_PATH is the primary loop prevention mechanism in BGP. When a router sees its own AS in the AS_PATH, it rejects the route.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP', 14.0, '{"ru": "Какой атрибут BGP используется для предотвращения петель внутри AS?"}', '{"ru": [{"id": "A", "text": "AS_PATH"}, {"id": "B", "text": "NEXT_HOP"}, {"id": "C", "text": "LOCAL_PREF"}, {"id": "D", "text": "MED"}]}', 'f21f0de1cccb59b2_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('a6fc2194-3de5-4d2e-a19b-6db34f4c55bb', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'Which command displays OSPF neighbor information on Junos?', '[{"id": "A", "text": "show ospf neighbor", "is_correct": true}, {"id": "B", "text": "show ospf interface", "is_correct": false}, {"id": "C", "text": "show ospf database", "is_correct": false}, {"id": "D", "text": "show protocols ospf neighbor", "is_correct": false}]', '''show ospf neighbor'' displays OSPF adjacency states, neighbor IDs, and interface information.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF', 10.0, '{"ru": "Какая команда отображает информацию о OSPF-соседях в Junos?"}', '{"ru": [{"id": "A", "text": "show ospf neighbor"}, {"id": "B", "text": "show ospf interface"}, {"id": "C", "text": "show ospf database"}, {"id": "D", "text": "show protocols ospf neighbor"}]}', '59643646c6489bab_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('6104c1a4-cf6d-46ea-b12a-44fb18c47dc6', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'In Junos, which policy action is used to reject a route?', '[{"id": "A", "text": "reject", "is_correct": true}, {"id": "B", "text": "deny", "is_correct": false}, {"id": "C", "text": "discard", "is_correct": false}, {"id": "D", "text": "drop", "is_correct": false}]', 'The ''reject'' action in a routing policy term rejects the route. In Junos, ''then reject'' is used in policy-options.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 14.0, '{"ru": "Какое action политики в Junos используется для отклонения маршрута?"}', '{"ru": [{"id": "A", "text": "reject"}, {"id": "B", "text": "deny"}, {"id": "C", "text": "discard"}, {"id": "D", "text": "drop"}]}', '3cd8fdedc3537e3c_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('1e57c417-adcc-404f-aeed-7e2ba0a01337', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'remember', 'What is the default preference for OSPF external routes in Junos?', '[{"id": "A", "text": "150", "is_correct": true}, {"id": "B", "text": "10", "is_correct": false}, {"id": "C", "text": "170", "is_correct": false}, {"id": "D", "text": "120", "is_correct": false}]', 'OSPF external routes (Type 5) have a default preference of 150 in Junos. OSPF internal routes have preference 10.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Fundamentals', 10.0, '{"ru": "Какое preference по умолчанию у внешних маршрутов OSPF в Junos?"}', '{"ru": [{"id": "A", "text": "150"}, {"id": "B", "text": "10"}, {"id": "C", "text": "170"}, {"id": "D", "text": "120"}]}', '49f0a3a0b7f757b0_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('73e69849-2c3d-4428-a86f-6c9b5d19d9c5', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 2, 'understand', 'Which two statements about OSPF areas are correct? (Select TWO)', '[{"id": "A", "text": "Area 0 is the backbone area", "is_correct": true}, {"id": "B", "text": "All non-backbone areas must connect to Area 0", "is_correct": true}, {"id": "C", "text": "Stub areas can contain ASBRs", "is_correct": false}, {"id": "D", "text": "NSSA allows external routes with Type 7 LSAs", "is_correct": false}]', 'Area 0 is the backbone; all non-backbone areas must connect to it. Stub areas cannot contain ASBRs. NSSA uses Type 7 LSAs.', '{"https://www.juniper.net/documentation/us/en/software/junos/ospf/"}', 'OSPF', 14.0, '{"ru": "Какие два утверждения о зонах OSPF верны? (Выберите ДВА)"}', '{"ru": [{"id": "A", "text": "Area 0 is the backbone area"}, {"id": "B", "text": "All non-backbone areas must connect to Area 0"}, {"id": "C", "text": "Stub areas can contain ASBRs"}, {"id": "D", "text": "NSSA allows external routes with Type 7 LSAs"}]}', '10db7e7282ecf2eb_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('952491c7-1f18-4cb9-a991-182b60f4e4f1', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What happens when a BGP route has multiple paths with the same LOCAL_PREF?', '[{"id": "A", "text": "The shortest AS_PATH wins", "is_correct": true}, {"id": "B", "text": "The lowest MED wins", "is_correct": false}, {"id": "C", "text": "The oldest route wins", "is_correct": false}, {"id": "D", "text": "EBGP over IBGP", "is_correct": false}]', 'After LOCAL_PREF, BGP compares AS_PATH length (shorter is better). Then it checks origin type, MED, EBGP vs IBGP, and IGP metric.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Path Selection', 14.0, '{"ru": "Что происходит, когда BGP-маршрут имеет несколько путей с одинаковым LOCAL_PREF?"}', '{"ru": [{"id": "A", "text": "The shortest AS_PATH wins"}, {"id": "B", "text": "The lowest MED wins"}, {"id": "C", "text": "The oldest route wins"}, {"id": "D", "text": "EBGP over IBGP"}]}', 'bdf3e2cdb038c640_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('8211a35c-890c-45d3-abfb-8cba2c548cb8', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 1, 'remember', 'Which command shows BGP routes in the routing table of a Junos device?', '[{"id": "A", "text": "show route protocol bgp", "is_correct": true}, {"id": "B", "text": "show bgp routes", "is_correct": false}, {"id": "C", "text": "show route bgp", "is_correct": false}, {"id": "D", "text": "show protocols bgp routes", "is_correct": false}]', '''show route protocol bgp'' displays BGP routes in the routing table. ''show bgp summary'' shows BGP peering status.', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Operations', 8.0, '{"ru": "Какая команда показывает BGP-маршруты в таблице маршрутизации Junos?"}', '{"ru": [{"id": "A", "text": "show route protocol bgp"}, {"id": "B", "text": "show bgp routes"}, {"id": "C", "text": "show route bgp"}, {"id": "D", "text": "show protocols bgp routes"}]}', '81e4045e51630f33_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('9b4d0189-d904-4e0f-872a-3890e1ba56b4', 'b0000000-0000-0000-0000-000000000010', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the purpose of the ''load-balance'' per-packet action in Junos?', '[{"id": "A", "text": "Distribute traffic across multiple equal-cost paths", "is_correct": true}, {"id": "B", "text": "Distribute traffic based on source IP", "is_correct": false}, {"id": "C", "text": "Create a static route for load sharing", "is_correct": false}, {"id": "D", "text": "Enable per-flow load balancing", "is_correct": false}]', '''load-balance per-packet'' enables per-packet load balancing across equal-cost multipath (ECMP) routes in the forwarding table.', '{"https://www.juniper.net/documentation/us/en/software/junos/routing-policy/"}', 'Routing Policy', 12.0, '{"ru": "Какова цель action ''load-balance per-packet'' в Junos?"}', '{"ru": [{"id": "A", "text": "Distribute traffic across multiple equal-cost paths"}, {"id": "B", "text": "Distribute traffic based on source IP"}, {"id": "C", "text": "Create a static route for load sharing"}, {"id": "D", "text": "Enable per-flow load balancing"}]}', 'c2a57e175dfefc17_gen_v2', true) ON CONFLICT (id) DO NOTHING;
