INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('ed21e284-d7ca-4bb0-be8b-e2150e1279df', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 3, 'understand', 'Which two MPLS applications typically use LDP for label distribution? (Select TWO) (variant 2).', '[{"id": "A", "text": "Layer 3 VPN (RFC 4364)", "is_correct": true}, {"id": "B", "text": "Layer 2 Circuit", "is_correct": true}, {"id": "C", "text": "MPLS-TE", "is_correct": false}, {"id": "D", "text": "RSVP", "is_correct": false}]', 'L3VPN and Layer 2 Circuit both use LDP for transport label distribution. MPLS-TE uses RSVP, and RSVP is a separate protocol (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Applications', 14.0, '{"ru": "Какие два приложения MPLS обычно используют LDP для распределения меток? (Выберите ДВА) (вариант 2)."}', '{"ru": [{"id": "A", "text": "Layer 3 VPN (RFC 4364)"}, {"id": "B", "text": "Layer 2 Circuit"}, {"id": "C", "text": "MPLS-TE"}, {"id": "D", "text": "RSVP"}]}', '9103710546f1adef_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('ff8e274c-38d6-4d6b-9393-79a0ff778a80', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does the ''policy-options'' community ''target:100:1'' specify in Junos (variant 2).', '[{"id": "A", "text": "Route target community for VPN: AS 100, local ID 1", "is_correct": true}, {"id": "B", "text": "BGP community 100:1", "is_correct": false}, {"id": "C", "text": "MSDP mesh group identifier", "is_correct": false}, {"id": "D", "text": "MPLS label range", "is_correct": false}]', 'Target communities follow format ''target:<ASN>:<local-assigned>''. Route targets control VRF import/export policies (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'VPN Policy', 12.0, '{"ru": "Что означает community ''target:100:1'' в ''policy-options'' Junos (вариант 2)."}', '{"ru": [{"id": "A", "text": "Route target community for VPN: AS 100, local ID 1"}, {"id": "B", "text": "BGP community 100:1"}, {"id": "C", "text": "MSDP mesh group identifier"}, {"id": "D", "text": "MPLS label range"}]}', '58594930424bf4af_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('47e4d865-2c03-47b5-9dda-22decb6d3e62', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a route reflector hierarchy, what is a ''client-to-client reflection'' (variant 2).', '[{"id": "A", "text": "RR reflects routes between its clients by default", "is_correct": true}, {"id": "B", "text": "Clients must peer directly with each other", "is_correct": false}, {"id": "C", "text": "RR only reflects routes from non-clients", "is_correct": false}, {"id": "D", "text": "Client-to-client reflection is disabled by default", "is_correct": false}]', 'By default, a BGP route reflector reflects routes learned from one client to all other clients. This can be disabled with ''no-client-to-client-reflection'' (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 14.0, '{"ru": "Что такое ''client-to-client reflection'' в иерархии route reflector (вариант 2)."}', '{"ru": [{"id": "A", "text": "RR reflects routes between its clients by default"}, {"id": "B", "text": "Clients must peer directly with each other"}, {"id": "C", "text": "RR only reflects routes from non-clients"}, {"id": "D", "text": "Client-to-client reflection is disabled by default"}]}', 'b607029b4f27fb43_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('e8815a6c-e0a9-41fe-a287-0d3cd2a87d9c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'Which command verifies LDP session status in Junos (variant 2).', '[{"id": "A", "text": "show ldp session", "is_correct": true}, {"id": "B", "text": "show mpls ldp session", "is_correct": false}, {"id": "C", "text": "show ldp neighbor", "is_correct": false}, {"id": "D", "text": "show protocols ldp status", "is_correct": false}]', '''show ldp session'' displays LDP session state, neighbor address, and label advertisement mode. ''show ldp neighbor'' shows discovery state (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP Operations', 8.0, '{"ru": "Какая команда проверяет статус LDP-сессии в Junos (вариант 2)."}', '{"ru": [{"id": "A", "text": "show ldp session"}, {"id": "B", "text": "show mpls ldp session"}, {"id": "C", "text": "show ldp neighbor"}, {"id": "D", "text": "show protocols ldp status"}]}', 'ba05056d6bf9f1f1_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('026ff559-0c47-42f1-98a6-8fa3da67e0e6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which BGP feature allows a route reflector to send routes to clients without modifying the NEXT_HOP (variant 3).', '[{"id": "A", "text": "Route reflection", "is_correct": true}, {"id": "B", "text": "Confederation", "is_correct": false}, {"id": "C", "text": "Multiprotocol BGP", "is_correct": false}, {"id": "D", "text": "Add-path", "is_correct": false}]', 'Route reflectors forward routes to clients without modifying NEXT_HOP, AS_PATH, or LOCAL_PREF. They add cluster ID and originator ID (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 12.0, '{"ru": "Какая функция BGP позволяет route reflector отправлять маршруты клиентам без изменения NEXT_HOP (вариант 3)."}', '{"ru": [{"id": "A", "text": "Route reflection"}, {"id": "B", "text": "Confederation"}, {"id": "C", "text": "Multiprotocol BGP"}, {"id": "D", "text": "Add-path"}]}', '432aeb134d86c470_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('dd973122-057c-4e68-a88c-55d4d2789d35', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP route reflector design, what is the purpose of the CLUSTER_LIST attribute (variant 3).', '[{"id": "A", "text": "Loop prevention among route reflectors", "is_correct": true}, {"id": "B", "text": "Selecting the best path", "is_correct": false}, {"id": "C", "text": "Influencing outbound traffic", "is_correct": false}, {"id": "D", "text": "Signaling MPLS labels", "is_correct": false}]', 'CLUSTER_LIST prevents routing loops between route reflectors. When a RR sees its own cluster ID in the CLUSTER_LIST, it ignores the route (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Design', 12.0, '{"ru": "Какова цель атрибута CLUSTER_LIST в дизайне BGP route reflector (вариант 3)."}', '{"ru": [{"id": "A", "text": "Loop prevention among route reflectors"}, {"id": "B", "text": "Selecting the best path"}, {"id": "C", "text": "Influencing outbound traffic"}, {"id": "D", "text": "Signaling MPLS labels"}]}', '4ecd99cdaa5ac437_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('8ead3976-54ce-4ca5-9e96-661956d9a72f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'Which MPLS signaling protocol uses UDP for label distribution (variant 3).', '[{"id": "A", "text": "LDP", "is_correct": true}, {"id": "B", "text": "RSVP-TE", "is_correct": false}, {"id": "C", "text": "MP-BGP", "is_correct": false}, {"id": "D", "text": "SR-MPLS", "is_correct": false}]', 'LDP (Label Distribution Protocol) uses UDP for discovery (hello messages on port 646) and TCP for session establishment and label exchange (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP', 12.0, '{"ru": "Какой протокол сигнализации MPLS использует UDP для распределения меток (вариант 3)."}', '{"ru": [{"id": "A", "text": "LDP"}, {"id": "B", "text": "RSVP-TE"}, {"id": "C", "text": "MP-BGP"}, {"id": "D", "text": "SR-MPLS"}]}', '818c8cd25e1a0a94_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('9b1abb77-eefa-4404-81ce-94a6b903b878', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What is the correct command to configure a VRF instance in Junos (variant 3).', '[{"id": "A", "text": "set routing-instances CUSTOMER-1 instance-type vrf", "is_correct": true}, {"id": "B", "text": "set vrf CUSTOMER-1", "is_correct": false}, {"id": "C", "text": "set protocols vrf CUSTOMER-1", "is_correct": false}, {"id": "D", "text": "set network-instance CUSTOMER-1 type vrf", "is_correct": false}]', 'VRFs are configured under ''routing-instances'' with ''instance-type vrf''. Route distinguisher and VRF import/export targets are also configured there (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, '{"ru": "Какая команда для настройки VRF-инстанса в Junos (вариант 3)."}', '{"ru": [{"id": "A", "text": "set routing-instances CUSTOMER-1 instance-type vrf"}, {"id": "B", "text": "set vrf CUSTOMER-1"}, {"id": "C", "text": "set protocols vrf CUSTOMER-1"}, {"id": "D", "text": "set network-instance CUSTOMER-1 type vrf"}]}', '09d0056f94dbf32b_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('008e80e3-957d-49bb-a92a-e947a13a488a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a BGP/MPLS IP VPN, what information does the Route Distinguisher provide (variant 3).', '[{"id": "A", "text": "Uniquely identifies a route from a specific VRF", "is_correct": true}, {"id": "B", "text": "Identifies the VPN target community", "is_correct": false}, {"id": "C", "text": "Specifies the MPLS label for the route", "is_correct": false}, {"id": "D", "text": "Defines the VRF export policy", "is_correct": false}]', 'RD makes a route unique across VPNs. Two VRFs can use overlapping IPs; RD + prefix = unique VPNv4 route (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'Layer 3 VPNs', 14.0, '{"ru": "Какую информацию предоставляет Route Distinguisher в BGP/MPLS IP VPN (вариант 3)."}', '{"ru": [{"id": "A", "text": "Uniquely identifies a route from a specific VRF"}, {"id": "B", "text": "Identifies the VPN target community"}, {"id": "C", "text": "Specifies the MPLS label for the route"}, {"id": "D", "text": "Defines the VRF export policy"}]}', '53a24d2229d72cfc_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('44021657-8756-472c-bc70-73f4be640d57', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'Which statement about MPLS-TE FRR (Fast Reroute) is correct (variant 3).', '[{"id": "A", "text": "FRR uses a pre-computed backup LSP to protect against link failures", "is_correct": true}, {"id": "B", "text": "FRR requires BGP to function", "is_correct": false}, {"id": "C", "text": "FRR is only available with LDP", "is_correct": false}, {"id": "D", "text": "FRR protects against node failures only", "is_correct": false}]', 'FRR pre-computes a backup LSP (bypass tunnel) that protects the primary LSP. Upon failure, traffic switches to the backup within 50ms (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS-TE', 14.0, '{"ru": "Какое утверждение о MPLS-TE FRR (Fast Reroute) верно (вариант 3)."}', '{"ru": [{"id": "A", "text": "FRR uses a pre-computed backup LSP to protect against link failures"}, {"id": "B", "text": "FRR requires BGP to function"}, {"id": "C", "text": "FRR is only available with LDP"}, {"id": "D", "text": "FRR protects against node failures only"}]}', '4fbdee81c5d55540_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('371db582-7798-4f84-8381-63184e27d77c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 3, 'understand', 'Which two MPLS applications typically use LDP for label distribution? (Select TWO) (variant 3).', '[{"id": "A", "text": "Layer 3 VPN (RFC 4364)", "is_correct": true}, {"id": "B", "text": "Layer 2 Circuit", "is_correct": true}, {"id": "C", "text": "MPLS-TE", "is_correct": false}, {"id": "D", "text": "RSVP", "is_correct": false}]', 'L3VPN and Layer 2 Circuit both use LDP for transport label distribution. MPLS-TE uses RSVP, and RSVP is a separate protocol (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Applications', 14.0, '{"ru": "Какие два приложения MPLS обычно используют LDP для распределения меток? (Выберите ДВА) (вариант 3)."}', '{"ru": [{"id": "A", "text": "Layer 3 VPN (RFC 4364)"}, {"id": "B", "text": "Layer 2 Circuit"}, {"id": "C", "text": "MPLS-TE"}, {"id": "D", "text": "RSVP"}]}', 'b1a3db16ed120355_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('fad7f0a8-6513-43dd-8840-a479f6b2ab24', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'What does the ''policy-options'' community ''target:100:1'' specify in Junos (variant 3).', '[{"id": "A", "text": "Route target community for VPN: AS 100, local ID 1", "is_correct": true}, {"id": "B", "text": "BGP community 100:1", "is_correct": false}, {"id": "C", "text": "MSDP mesh group identifier", "is_correct": false}, {"id": "D", "text": "MPLS label range", "is_correct": false}]', 'Target communities follow format ''target:<ASN>:<local-assigned>''. Route targets control VRF import/export policies (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/l3vpn/"}', 'VPN Policy', 12.0, '{"ru": "Что означает community ''target:100:1'' в ''policy-options'' Junos (вариант 3)."}', '{"ru": [{"id": "A", "text": "Route target community for VPN: AS 100, local ID 1"}, {"id": "B", "text": "BGP community 100:1"}, {"id": "C", "text": "MSDP mesh group identifier"}, {"id": "D", "text": "MPLS label range"}]}', '34039ef3b520fddd_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('a486d59b-12aa-4660-97d3-9d476942f79a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'In a route reflector hierarchy, what is a ''client-to-client reflection'' (variant 3).', '[{"id": "A", "text": "RR reflects routes between its clients by default", "is_correct": true}, {"id": "B", "text": "Clients must peer directly with each other", "is_correct": false}, {"id": "C", "text": "RR only reflects routes from non-clients", "is_correct": false}, {"id": "D", "text": "Client-to-client reflection is disabled by default", "is_correct": false}]', 'By default, a BGP route reflector reflects routes learned from one client to all other clients. This can be disabled with ''no-client-to-client-reflection'' (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/bgp/"}', 'BGP Route Reflection', 14.0, '{"ru": "Что такое ''client-to-client reflection'' в иерархии route reflector (вариант 3)."}', '{"ru": [{"id": "A", "text": "RR reflects routes between its clients by default"}, {"id": "B", "text": "Clients must peer directly with each other"}, {"id": "C", "text": "RR only reflects routes from non-clients"}, {"id": "D", "text": "Client-to-client reflection is disabled by default"}]}', '48c358f55ffdeb38_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('6a224b02-ebc5-496a-9d89-d56e5f4b4112', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'Which command verifies LDP session status in Junos (variant 3).', '[{"id": "A", "text": "show ldp session", "is_correct": true}, {"id": "B", "text": "show mpls ldp session", "is_correct": false}, {"id": "C", "text": "show ldp neighbor", "is_correct": false}, {"id": "D", "text": "show protocols ldp status", "is_correct": false}]', '''show ldp session'' displays LDP session state, neighbor address, and label advertisement mode. ''show ldp neighbor'' shows discovery state (Variant 3).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS LDP Operations', 8.0, '{"ru": "Какая команда проверяет статус LDP-сессии в Junos (вариант 3)."}', '{"ru": [{"id": "A", "text": "show ldp session"}, {"id": "B", "text": "show mpls ldp session"}, {"id": "C", "text": "show ldp neighbor"}, {"id": "D", "text": "show protocols ldp status"}]}', 'e2992699eaafb390_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('a90e1a73-af2f-4027-80e6-d5fe44eb0d40', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos?', '[{"id": "A", "text": "16 through 1023", "is_correct": true}, {"id": "B", "text": "0 through 15", "is_correct": false}, {"id": "C", "text": "1024 through 65535", "is_correct": false}, {"id": "D", "text": "1 through 1000", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, '{"ru": "Каков диапазон динамических MPLS-меток по умолчанию в Junos?"}', '{"ru": [{"id": "A", "text": "16 through 1023"}, {"id": "B", "text": "0 through 15"}, {"id": "C", "text": "1024 through 65535"}, {"id": "D", "text": "1 through 1000"}]}', 'a5f05d08f0ffdfdb_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('f7cc9e95-9a8b-4225-98a4-16890c060668', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', 'Which command shows the MPLS label-switched path (LSP) information in Junos?', '[{"id": "A", "text": "show mpls lsp", "is_correct": true}, {"id": "B", "text": "show mpls path", "is_correct": false}, {"id": "C", "text": "show rsvp lsp", "is_correct": false}, {"id": "D", "text": "show ldp lsp", "is_correct": false}]', '''show mpls lsp'' displays LSP status, path, and statistics. It shows ingress, transit, and egress LSPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 14.0, '{"ru": "Какая команда показывает информацию о LSP в Junos?"}', '{"ru": [{"id": "A", "text": "show mpls lsp"}, {"id": "B", "text": "show mpls path"}, {"id": "C", "text": "show rsvp lsp"}, {"id": "D", "text": "show ldp lsp"}]}', '810c23db265399f2_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('68755f09-7cce-4a74-a8c0-9ec6a35e1dc5', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the purpose of the MPLS explicit NULL label (value 0)?', '[{"id": "A", "text": "The egress router pops the label and performs an IP lookup", "is_correct": true}, {"id": "B", "text": "The penultimate hop pops the label", "is_correct": false}, {"id": "C", "text": "It indicates an IPv6 payload", "is_correct": false}, {"id": "D", "text": "It is used for OAM operations", "is_correct": false}]', 'Explicit NULL (label 0) tells the penultimate hop to retain the label. The egress router pops it and does an IP lookup. Used when QoS information is in the MPLS header.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Label Operations', 12.0, '{"ru": "Каково назначение explicit NULL метки MPLS (значение 0)?"}', '{"ru": [{"id": "A", "text": "The egress router pops the label and performs an IP lookup"}, {"id": "B", "text": "The penultimate hop pops the label"}, {"id": "C", "text": "It indicates an IPv6 payload"}, {"id": "D", "text": "It is used for OAM operations"}]}', '58047d0834e68aee_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('008cda22-c755-4b0e-a73f-4fc380baa0ad', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'Which RSVP message is used to tear down an established LSP?', '[{"id": "A", "text": "PathTear", "is_correct": true}, {"id": "B", "text": "ResvTear", "is_correct": false}, {"id": "C", "text": "PathErr", "is_correct": false}, {"id": "D", "text": "ResvErr", "is_correct": false}]', 'PathTear travels from ingress to egress tearing down the LSP. ResvTear travels upstream from egress to ingress.', '{"https://www.juniper.net/documentation/us/en/software/junos/rsvp/"}', 'RSVP-TE', 14.0, '{"ru": "Какое сообщение RSVP используется для разрыва установленного LSP?"}', '{"ru": [{"id": "A", "text": "PathTear"}, {"id": "B", "text": "ResvTear"}, {"id": "C", "text": "PathErr"}, {"id": "D", "text": "ResvErr"}]}', '2a85fd7d78f21611_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('e4344450-95ee-4843-a1e7-d990160937cf', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'In the context of MPLS, what is PHP?', '[{"id": "A", "text": "Penultimate Hop Popping — the second-to-last router removes the label", "is_correct": true}, {"id": "B", "text": "Path Hop Protocol — a signaling mechanism", "is_correct": false}, {"id": "C", "text": "Per-Hop Policing — QoS enforcement", "is_correct": false}, {"id": "D", "text": "Provider Hub Point — a central aggregation router", "is_correct": false}]', 'PHP is when the penultimate hop router pops the MPLS label before forwarding the packet to the egress router. This reduces the load on the egress router.', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Operations', 12.0, '{"ru": "Что такое PHP в контексте MPLS?"}', '{"ru": [{"id": "A", "text": "Penultimate Hop Popping — the second-to-last router removes the label"}, {"id": "B", "text": "Path Hop Protocol — a signaling mechanism"}, {"id": "C", "text": "Per-Hop Policing — QoS enforcement"}, {"id": "D", "text": "Provider Hub Point — a central aggregation router"}]}', 'd11e9df7440166bb_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('7f91a4ec-2c72-403a-ac87-a86ed631c40b', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', 'What is the default MPLS label range for dynamic labels in Junos (variant 2).', '[{"id": "A", "text": "16 through 1023", "is_correct": true}, {"id": "B", "text": "0 through 15", "is_correct": false}, {"id": "C", "text": "1024 through 65535", "is_correct": false}, {"id": "D", "text": "1 through 1000", "is_correct": false}]', 'Junos uses label range 0-15 for reserved labels (e.g., 0=IPv4 NULL, 3=implicit NULL). Dynamic LDP/RSVP labels start from 16 through 1023 by default (Variant 2).', '{"https://www.juniper.net/documentation/us/en/software/junos/mpls/"}', 'MPLS Fundamentals', 14.0, '{"ru": "Каков диапазон динамических MPLS-меток по умолчанию в Junos (вариант 2)."}', '{"ru": [{"id": "A", "text": "16 through 1023"}, {"id": "B", "text": "0 through 15"}, {"id": "C", "text": "1024 through 65535"}, {"id": "D", "text": "1 through 1000"}]}', 'aa3f4ffd6b905834_gen_v2', true) ON CONFLICT (id) DO NOTHING;
