INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('5feb4b3e-f682-4980-b591-ff34b23de9b0', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'Which encapsulation technology is commonly used for overlay networks in data center fabrics?', '[{"id": "A", "text": "VXLAN", "is_correct": true}, {"id": "B", "text": "GRE", "is_correct": false}, {"id": "C", "text": "IP-IP", "is_correct": false}, {"id": "D", "text": "MPLS", "is_correct": false}]', 'VXLAN (Virtual Extensible LAN) is the most common overlay encapsulation in modern DC fabrics. It uses UDP encapsulation (port 4789) and supports up to 16M segments.', '{"https://www.juniper.net/documentation/us/en/software/junos/vxlan/"}', 'Data Center Overlays', 14.0, '{"ru": "Какая технология инкапсуляции используется для overlay-сетей в дата-центрах?"}', '{"ru": [{"id": "A", "text": "VXLAN"}, {"id": "B", "text": "GRE"}, {"id": "C", "text": "IP-IP"}, {"id": "D", "text": "MPLS"}]}', '33bb4484c16a91ae_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('57efd870-3ed8-4678-91ea-b6f8bd039cf6', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'In Juniper EVPN-VXLAN, what is the role of the VTEP?', '[{"id": "A", "text": "VXLAN Tunnel End Point — encapsulates/decapsulates VXLAN traffic", "is_correct": true}, {"id": "B", "text": "Virtual Tenant End Point — manages tenant routing", "is_correct": false}, {"id": "C", "text": "VXLAN Traffic Engineering Path", "is_correct": false}, {"id": "D", "text": "Virtual Topology Entry Point", "is_correct": false}]', 'VTEP is the device that performs VXLAN encapsulation (adding UDP+VXLAN header) and decapsulation. Leaf switches typically act as VTEPs.', '{"https://www.juniper.net/documentation/us/en/software/junos/evpn-vxlan/"}', 'EVPN-VXLAN', 14.0, '{"ru": "Какова роль VTEP в EVPN-VXLAN Juniper?"}', '{"ru": [{"id": "A", "text": "VXLAN Tunnel End Point — encapsulates/decapsulates VXLAN traffic"}, {"id": "B", "text": "Virtual Tenant End Point — manages tenant routing"}, {"id": "C", "text": "VXLAN Traffic Engineering Path"}, {"id": "D", "text": "Virtual Topology Entry Point"}]}', '58f6d039ffdd8686_gen_v2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, body_translations, options_translations, content_hash, is_active) VALUES ('3e53a414-f88d-4995-87c1-90295e5df44c', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 2, 'understand', 'What is a QFX5110 Virtual Chassis Fabric (VCF)?', '[{"id": "A", "text": "Multiple QFX switches operating as a single logical switch", "is_correct": true}, {"id": "B", "text": "A physical chassis with multiple line cards", "is_correct": false}, {"id": "C", "text": "A virtual router instance", "is_correct": false}, {"id": "D", "text": "An MX series virtual router", "is_correct": false}]', 'VCF allows multiple QFX switches to be interconnected via VCP (Virtual Chassis Ports) to form a single logical switch with unified management.', '{"https://www.juniper.net/documentation/us/en/software/junos/virtual-chassis/"}', 'Virtual Chassis', 14.0, '{"ru": "Что такое Virtual Chassis Fabric (VCF) QFX5110?"}', '{"ru": [{"id": "A", "text": "Multiple QFX switches operating as a single logical switch"}, {"id": "B", "text": "A physical chassis with multiple line cards"}, {"id": "C", "text": "A virtual router instance"}, {"id": "D", "text": "An MX series virtual router"}]}', '084557483b928be7_gen_v2', true) ON CONFLICT (id) DO NOTHING;
